// ============================================================
// WF1 - Node Code: susun response pencarian resi.
// - Ambil query param `resi` (bisa banyak, dipisah koma).
// - Normalisasi tiap resi: trim + uppercase.
// - Cari di rows sheet Tracking.
// - Parse Riwayat_Posisi_JSON dengan try/catch (aman dari JSON korup).
// - Resi tak ditemukan => { no_resi, found:false }.
// ============================================================

// Rows sheet dari node sebelumnya (Baca Sheet Tracking).
const rows = $items('Baca Sheet Tracking').map(i => i.json);

// Ambil query dari webhook. n8n menaruh query di .query.
const webhookData = $items('Webhook GET tracking-get')[0].json;
const query = webhookData.query || {};
const resiParamRaw = query.resi || '';

// Split daftar resi berdasarkan koma, normalisasi, buang yang kosong.
const daftarResi = String(resiParamRaw)
  .split(',')
  .map(r => r.trim().toUpperCase())
  .filter(r => r.length > 0);

// Bangun index rows berdasarkan No_Resi (uppercase) untuk lookup cepat.
const indexResi = {};
for (const row of rows) {
  const key = String(row.No_Resi || '').trim().toUpperCase();
  if (key) indexResi[key] = row;
}

// Susun hasil untuk tiap resi yang diminta.
const hasil = [];
for (const resi of daftarResi) {
  const row = indexResi[resi];

  if (!row) {
    // Resi tidak ditemukan di sheet.
    hasil.push({ no_resi: resi, found: false });
    continue;
  }

  // Parse riwayat JSON dengan aman.
  let riwayat = [];
  let riwayatError = false;
  const raw = row.Riwayat_Posisi_JSON;
  if (raw !== undefined && raw !== null && String(raw).trim() !== '') {
    try {
      const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
      riwayat = Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      // JSON korup: kembalikan riwayat kosong + flag error.
      riwayat = [];
      riwayatError = true;
    }
  }

  const entri = {
    no_resi: String(row.No_Resi || resi),
    found: true,
    pengirim: row.Pengirim || '',
    penerima: row.Penerima || '',
    status_terakhir: row.Status_Terakhir || '',
    timestamp_update: row.Timestamp_Update || '',
    riwayat: riwayat
  };
  if (riwayatError) entri.riwayat_error = true;

  hasil.push(entri);
}

// Kembalikan satu item berisi array hasil (dipakai node Respond).
return [{ json: { data: hasil, total: hasil.length } }];
